### Code example

```
return streamText({
    model: createFallback({
      models: [
        provider.languageModel("gemini-2-flash-lite"),
        provider.languageModel("gemini-2-flash"),
        provider.languageModel("gpt-4o-mini"),
      ],
      shouldRetryThisError: (error: Error) => {
        if (TypeValidationError.isInstance(error)) {
          return true;
        }

        const defaultHandler = error.message.toLowerCase();
        if (defaultHandler.includes('api key') ||
          defaultHandler.includes('no such') ||
          error.name === 'AI_APICallError' ||
          error.name === 'AI_NoSuchModelError') {
          console.log('Retrying due to API or model error');
          return true;
        }

        return false;
      },
      onError: (error, modelId) => {
        if (!(error.name === 'AI_TypeValidationError' &&
          error.message.includes('candidates') &&
          error.message.includes('content.parts'))) {
          console.error(`\nError with model ${modelId}:`, error, "\n");
        }
      },
      retryAfterOutput: false,
      modelResetInterval: 120000,
    }),
    system: agent(),
    messages: convertToCoreMessages(messages),
    maxSteps: 5,
    temperature: 0,
    experimental_telemetry: { isEnabled: true },
    experimental_transform: smoothStream({ chunking: "word" }),
    experimental_activeTools: ALL_TOOLS,
    tools: {
      behavior,
      event,
      form,
      media,
      report,
      navigation,
    },
    experimental_repairToolCall: async ({
      toolCall,
      tools,
      parameterSchema,
      error,
    }) => {
      if (NoSuchToolError.isInstance(error)) {
        return null;
      }

      const tool = tools[toolCall.toolName as keyof typeof tools];

      const { object: repairedArgs } = await generateObject({
        model: openai('gpt-4o-mini', { structuredOutputs: true }),
        schema: tool.parameters,
        prompt: [
          `The model tried to call the tool "${toolCall.toolName}"` +
          ` with the following arguments:`,
          JSON.stringify(toolCall.args),
          `The tool accepts the following schema:`,
          JSON.stringify(parameterSchema(toolCall)),
          'Please fix the arguments.',
        ].join('\n'),
      });

      return { ...toolCall, args: JSON.stringify(repairedArgs) };
    },
  }).toDataStreamResponse();
